// src/pages/SDM.jsx
import React, { useEffect, useRef } from "react";
import { useSearchParams } from "react-router-dom";
import { useUI } from "../context/UIContext";
import Button from "../components/common/Button";
import Card from "../components/common/Card";
import styles from "../SDM.module.css";
import eveVideo from "../assets/eve_sdm_talk.mp4";

// 引用常量檔內容
import { topicDescriptions } from "../constants/sdm";

const SDM = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const { setHeroData } = useUI();
  const videoRef = useRef(null);

  const step = searchParams.get("step") || "SELECT";
  const selectedTopicId = searchParams.get("topic");

  useEffect(() => {
    setHeroData(null);
  }, [setHeroData]);

  // 轉換常量資料供 Map 渲染
  const topics = Object.keys(topicDescriptions).map((key) => ({
    id: key,
    ...topicDescriptions[key],
  }));

  // 建議修改 SDM.jsx 的 return 區塊，針對不同步驟顯示不同按鈕
  return (
    <div className={styles.pageContainer}>
      {/* ... 其他內容 ... */}
      <div className={styles.contentSection}>
        {step === "SELECT" ? (
          <>
            <h2>請選擇您想了解的主題</h2>
            {topics.map((item) => (
              <Card
                key={item.id}
                title={item.label} // 確保這裡對應到 constants/sdm.js 的 label
                description={item.description} // 確保這裡對應到 constants/sdm.js 的 description
                isActive={selectedTopicId === item.id}
                onClick={() =>
                  setSearchParams({ step: "SELECT", topic: item.id })
                }
              />
            ))}
            <Button
              onClick={() =>
                selectedTopicId &&
                setSearchParams({ step: "INTRO", topic: selectedTopicId })
              }
              fullWidth
            >
              確認選擇並查看詳情 ➔
            </Button>
            {/* 加入這個返回按鈕，讓用戶可以回到上一層選擇「治療決策輔助」或「AI機器人」 */}
            <Button
              variant="outline"
              onClick={() => navigate(-1)} // 使用 react-router 的 navigate 回上一頁
              fullWidth
              style={{ marginTop: "10px" }}
            >
              返回上一頁
            </Button>
          </>
        ) : (
          <div>
            <div
              dangerouslySetInnerHTML={{
                __html: topicDescriptions[selectedTopicId]?.content,
              }}
            />
            {/* 在詳情頁，按鈕返回 SELECT 步驟 */}
            <Button
              variant="outline"
              onClick={() => setSearchParams({ step: "SELECT", topic: "" })}
              fullWidth
            >
              返回選擇主題
            </Button>
          </div>
        )}
      </div>
    </div>
  );
};

export default SDM;
